
.title-bar {
  padding: 10px;
  background: var(--c-surface);
  border-bottom: 3px solid var(--c-border);
  transition: box-shadow 0.4s ease;
}

.title-bar.glowing {
  box-shadow: inset 0 0 0 2px var(--c-accent-gold);
}

.title-row {
  margin-bottom: 6px;
}

.title-name {
  font-weight: bold;
  font-size: 0.85rem;
  margin-right: 8px;
}

.sisters-row {
  display: flex;
  gap: 8px;
}

.sister-chip {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 4px;
  border: 1.5px solid var(--c-border);
  padding: 3px 6px;
  background: var(--c-background);
}

.sister-icon {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--c-primary);
  color: var(--c-surface);
  font-size: 0.65rem;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.sister-name {
  font-size: 0.75rem;
  flex: 1;
}

.sister-value {
  font-size: 0.75rem;
  font-weight: bold;
}
