
.item-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px;
}

.item-cell {
  border: 1.5px solid var(--c-border);
  background: var(--c-surface);
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.item-label {
  font-size: 0.7rem;
  color: var(--c-text-muted);
}

.item-value {
  font-size: 0.82rem;
  font-weight: bold;
}

@media (max-width: 600px) {
  .item-grid {
    grid-template-columns: 1fr;
  }
}
