
.sister-panel {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.section-head {
  font-size: 0.85rem;
  font-weight: bold;
  border-bottom: 2px solid var(--c-primary);
  display: inline-block;
  margin: 8px 0 4px;
}

.status-line {
  font-size: 0.8rem;
  color: var(--c-text-muted);
  font-style: italic;
  padding: 2px 0;
}
