
.user-panel {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.rename-badge {
  align-self: flex-start;
  border: 1.5px solid var(--c-border);
  padding: 2px 8px;
  font-size: 0.72rem;
  color: var(--c-text-muted);
  margin-bottom: 4px;
}

.rename-badge.renamed {
  border-color: var(--c-accent-gold);
  color: var(--c-accent-gold);
  font-weight: bold;
}

.section-head {
  font-size: 0.85rem;
  font-weight: bold;
  border-bottom: 2px solid var(--c-primary);
  display: inline-block;
  margin: 8px 0 4px;
}

.body-card {
  border: 1.5px solid var(--c-border);
  background: var(--c-surface);
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.body-row {
  font-size: 0.8rem;
}

.body-label {
  display: inline-block;
  min-width: 3.2em;
  color: var(--c-text-muted);
  margin-right: 4px;
}
